edits.replacement:
.scard .ss b{ color:var(--amber); font-weight:600; }
/* v16.xx, seen on the 4K YOUR STATS screenshot (2026-10-08): the card titles were 11px and the lines under them 12px, and the
   150px cards stood seven to a row with empty space beside them. Bigger print and wider cards that fill the row. */
#statgrid{ grid-template-columns:repeat(auto-fit,minmax(190px,1fr)); gap:9px; }
.scard{ padding:10px 12px; }
.scard .sk{ font-size:13px; }
.scard .sv{ font-size:28px; }
.scard .sv.word{ font-size:19px; }
.scard .ss{ font-size:14px; line-height:1.35; }

check:
{v:'VER',what:'the stat cards are readable: titles 13px, figures 28px and the lines under them 14px',
 run:function(){
   if(typeof renderStatCards!=='function') return 'SKIP: no stats page here';
   var bad=[], c, f;
   try{ renderStatCards(); }catch(e){ return 'threw: '+(e&&e.message||e); }
   c=document.querySelector('#statgrid .scard'); if(!c) return 'SKIP: no stat cards';
   f=function(sel){ var e=c.querySelector(sel); return e?parseFloat(getComputedStyle(e).fontSize):0; };
   if(!(f('.sk')>=12.9)) bad.push('the title is '+f('.sk')+'px');
   if(!(f('.sv')>=27.9||(c.querySelector('.sv.word')&&f('.sv')>=18.9))) bad.push('the figure is '+f('.sv')+'px');
   if(c.querySelector('.ss')&&!(f('.ss')>=13.9)) bad.push('the line under it is '+f('.ss')+'px');
   return bad.length?bad.join('; '):null; }},
